mutex_key <- function(a, b) paste(sort(c(a, b)), collapse=",")
new_mutexes <- function() new.env(hash=TRUE, parent=emptyenv())
mutex_has <- function(mutexes, a, b) exists(mutex_key(a, b), mutexes, inherits=FALSE)
mutex_count <- function(mutexes) length(ls(mutexes, all.names=TRUE))
pair_conflict <- function(facts, mutexes) {
    for (i in seq_along(facts)) if (i < length(facts)) for (j in seq.int(i+1L, length(facts))) {
        if (mutex_has(mutexes, facts[i], facts[j])) return(TRUE)
    }
    FALSE
}
graph_conflict <- function(a, b, mutexes) {
    if (any(a$delete %in% union(b$pre, b$add)) || any(b$delete %in% union(a$pre, a$add))) return(TRUE)
    for (p in a$pre) for (q in b$pre) if (mutex_has(mutexes, p, q)) return(TRUE)
    FALSE
}
new_graph_frame <- function(type, level, goals, position=1L, chosen=integer()) {
    frame <- new.env(parent=emptyenv())
    frame$type <- type
    frame$level <- level
    frame$goals <- goals
    frame$position <- position
    frame$chosen <- chosen
    frame$stage <- 0L
    frame
}
solve_graphplan <- function(actions, initial, goal, limit) {
    facts <- list(initial)
    mutexes <- list(new_mutexes())
    levels <- exclusive_levels <- achiever_levels <- list()
    memo <- new.env(hash=TRUE, parent=emptyenv())
    lines <- character()
    counts <- new.env(parent=emptyenv())
    counts$searched <- counts$memo_hits <- counts$tried <- 0L
    extract <- function(level, goals) {
        stack <- list(new_graph_frame("extract", level, goals))
        result <- NULL
        while (length(stack)) {
            frame <- stack[[length(stack)]]
            pop_frame <- function() stack <<- head(stack, -1)
            key <- paste(frame$level, state_key(frame$goals))
            if (frame$type == "extract") {
                if (frame$stage == 0L) {
                    if (frame$level == 0L) {
                        result <- list()
                        pop_frame()
                    } else if (exists(key, memo, inherits=FALSE)) {
                        counts$memo_hits <- counts$memo_hits+1L
                        result <- NULL
                        pop_frame()
                    } else {
                        counts$searched <- counts$searched+1L
                        frame$stage <- 1L
                        stack[[length(stack)+1L]] <- new_graph_frame("assign", frame$level, frame$goals)
                    }
                } else {
                    if (is.null(result)) memo[[key]] <- TRUE
                    pop_frame()
                }
                next
            }
            elements <- levels[[frame$level]]
            if (frame$stage == 0L) {
                repeat {
                    if (frame$position > length(frame$goals)) break
                    covered <- any(vapply(frame$chosen, function(i) frame$goals[frame$position] %in% elements[[i]]$add, FALSE))
                    if (!covered) break
                    frame$position <- frame$position+1L
                }
                if (frame$position > length(frame$goals)) {
                    previous <- sort(unique(unlist(lapply(frame$chosen, function(i) elements[[i]]$pre), use.names=FALSE)))
                    frame$stage <- 2L
                    stack[[length(stack)+1L]] <- new_graph_frame("extract", frame$level-1L, previous)
                } else {
                    frame$producers <- achiever_levels[[frame$level]][[as.character(frame$goals[frame$position])]]
                    frame$next_producer <- 1L
                    frame$stage <- 1L
                }
            } else if (frame$stage == 2L) {
                if (!is.null(result)) {
                    layer <- sort(vapply(Filter(function(e) !is.na(e$number), elements[frame$chosen]), function(e) e$number, 0L))
                    result[[length(result)+1L]] <- layer
                }
                pop_frame()
            } else if (frame$stage == 3L) {
                if (!is.null(result)) pop_frame() else frame$stage <- 1L
            } else {
                selected <- 0L
                while (frame$next_producer <= length(frame$producers)) {
                    i <- frame$producers[frame$next_producer]
                    frame$next_producer <- frame$next_producer+1L
                    conflict <- any(vapply(frame$chosen, function(j) mutex_has(exclusive_levels[[frame$level]], i, j), FALSE))
                    if (!conflict) {
                        selected <- i
                        break
                    }
                }
                if (selected == 0L) {
                    result <- NULL
                    pop_frame()
                } else {
                    counts$tried <- counts$tried+1L
                    frame$stage <- 3L
                    stack[[length(stack)+1L]] <- new_graph_frame("assign", frame$level,
                        frame$goals, frame$position+1L, c(frame$chosen, selected))
                }
            }
        }
        result
    }
    finish <- function(status, layers=list()) {
        list(status=status, plan=as.integer(unlist(layers, use.names=FALSE)), layers=layers, lines=lines,
            expanded=counts$searched, generated=counts$tried, memo_hits=counts$memo_hits)
    }
    for (level in 0:limit) {
        current <- facts[[level+1L]]
        current_mutexes <- mutexes[[level+1L]]
        lines <- c(lines, paste0("fact level ", level, ": facts=", length(current), " mutexes=", mutex_count(current_mutexes)))
        possible <- all(goal %in% current) && !pair_conflict(goal, current_mutexes)
        if (possible) {
            before_search <- counts$searched
            before_hits <- counts$memo_hits
            layers <- extract(level, sort(goal))
            outcome <- if (is.null(layers)) "fail" else "success"
            lines <- c(lines, paste0("extract level ", level, ": ", outcome,
                " searched=", counts$searched-before_search, " memo_hits=", counts$memo_hits-before_hits))
            if (!is.null(layers)) return(finish("solved", layers))
        } else if (level >= 1L && length(current) == length(facts[[level]]) &&
            mutex_count(current_mutexes) == mutex_count(mutexes[[level]])) return(finish("unreachable"))
        if (level == limit) return(finish("level limit"))
        elements <- Filter(function(a) all(a$pre %in% current) && !pair_conflict(a$pre, current_mutexes), actions)
        action_count <- length(elements)
        for (p in sort(current)) elements[[length(elements)+1L]] <- list(number=NA_integer_, pre=p, add=p, delete=integer())
        exclusive <- new_mutexes()
        for (i in seq_along(elements)) if (i < length(elements)) for (j in seq.int(i+1L, length(elements))) {
            if (graph_conflict(elements[[i]], elements[[j]], current_mutexes)) exclusive[[mutex_key(i, j)]] <- TRUE
        }
        lines <- c(lines, paste0("action level ", level, ": actions=", action_count,
            " noops=", length(current), " mutexes=", mutex_count(exclusive)))
        achievers <- list()
        for (i in seq_along(elements)) for (p in elements[[i]]$add) {
            key <- as.character(p)
            achievers[[key]] <- c(achievers[[key]], i)
        }
        for (key in names(achievers)) {
            producers <- achievers[[key]]
            ranks <- vapply(producers, function(i) if (is.na(elements[[i]]$number)) -1L else elements[[i]]$number, 0L)
            achievers[[key]] <- producers[order(ranks)]
        }
        following <- sort(as.integer(names(achievers)))
        following_mutexes <- new_mutexes()
        for (i in seq_along(following)) if (i < length(following)) for (j in seq.int(i+1L, length(following))) {
            p <- following[i]
            q <- following[j]
            all_exclusive <- TRUE
            for (x in achievers[[as.character(p)]]) {
                for (y in achievers[[as.character(q)]]) if (x == y || !mutex_has(exclusive, x, y)) {
                    all_exclusive <- FALSE
                    break
                }
                if (!all_exclusive) break
            }
            if (all_exclusive) following_mutexes[[mutex_key(p, q)]] <- TRUE
        }
        levels[[length(levels)+1L]] <- elements
        exclusive_levels[[length(exclusive_levels)+1L]] <- exclusive
        achiever_levels[[length(achiever_levels)+1L]] <- achievers
        facts[[length(facts)+1L]] <- following
        mutexes[[length(mutexes)+1L]] <- following_mutexes
    }
    finish("level limit")
}

subtype <- function(parents, actual, expected) {
    while (!is.null(actual)) {
        if (actual == expected) return(TRUE)
        actual <- parents[[actual]]
    }
    FALSE
}
predicate_classes <- function(domain) {
    fluent <- unique(unlist(lapply(domain$actions, function(a) vapply(a$effects, function(l) l$atom[1], "")), use.names=FALSE))
    list(fluent=fluent, static=setdiff(domain$predicate_order, fluent))
}
substitute <- function(atom, assignment) c(atom[1], unname(assignment[atom[-1]]))
ground <- function(domain, problem) {
    objects_by_type <- setNames(lapply(domain$type_order, function(kind) {
        problem$object_order[vapply(problem$object_order, function(name) subtype(domain$parents, problem$objects[[name]], kind), FALSE)]
    }), domain$type_order)
    atom_store <- new.env(hash=TRUE, parent=emptyenv())
    key_atom <- function(atom) {
        key <- notation(atom)
        atom_store[[key]] <- atom
        key
    }
    initial_atoms <- vapply(problem$initial, key_atom, "")
    candidates <- list()
    statistics <- list()
    for (schema in domain$actions) {
        choices <- lapply(schema$parameters, function(p) objects_by_type[[p[2]]])
        counts <- c(prod(lengths(choices)), 0L, 0L)
        assign_objects <- function(arguments, index) {
            if (index <= length(choices)) {
                for (name in choices[[index]]) assign_objects(c(arguments, name), index+1L)
                return(invisible(NULL))
            }
            binding <- setNames(arguments, vapply(schema$parameters, function(p) p[1], ""))
            positive <- negative <- character()
            for (literal in schema$condition) {
                bound <- substitute(literal$atom, binding)
                if (bound[1] == "=") {
                    truth <- bound[2] == bound[3]
                } else if (bound[1] %in% domain$static) {
                    truth <- key_atom(bound) %in% initial_atoms
                } else {
                    key <- key_atom(bound)
                    if (literal$sign) positive <- union(positive, key) else negative <- union(negative, key)
                    next
                }
                if (truth != literal$sign) return(invisible(NULL))
            }
            adds <- deletes <- character()
            for (literal in schema$effects) {
                key <- key_atom(substitute(literal$atom, binding))
                if (literal$sign) adds <- union(adds, key) else deletes <- union(deletes, key)
            }
            candidates[[length(candidates)+1L]] <<- list(source=schema, arguments=arguments, cost=schema$cost,
                pre=positive, neg=negative, add=adds, delete=setdiff(deletes, adds))
            counts[2] <<- counts[2]+1L
        }
        assign_objects(character(), 1L)
        statistics[[schema$name]] <- counts
    }
    reachable <- initial_atoms[vapply(problem$initial, function(a) a[1] %in% domain$fluent, FALSE)]
    accepted <- rep(FALSE, length(candidates))
    repeat {
        changed <- FALSE
        for (i in seq_along(candidates)) {
            candidate <- candidates[[i]]
            if (!accepted[i] && all(candidate$pre %in% reachable)) {
                accepted[i] <- TRUE
                reachable <- union(reachable, candidate$add)
                name <- candidate$source$name
                statistics[[name]][3] <- statistics[[name]][3]+1L
                changed <- TRUE
            }
        }
        if (!changed) break
    }
    fact_keys <- unique(reachable)
    facts <- lapply(fact_keys, function(key) atom_store[[key]])
    sort_keys <- vapply(facts, function(atom) paste0(sprintf("%02d", match(atom[1], domain$predicate_order)),
        paste(sprintf("%02d", match(atom[-1], problem$object_order)), collapse="")), "")
    order <- order(sort_keys, method="radix")
    facts <- facts[order]
    fact_keys <- fact_keys[order]
    fact_numbers <- setNames(seq_along(fact_keys)-1L, fact_keys)
    actions <- list()
    for (i in which(accepted)) {
        candidate <- candidates[[i]]
        mapped <- lapply(candidate[c("pre", "neg", "add", "delete")], function(values) sort(unname(fact_numbers[intersect(values, fact_keys)])))
        actions[[length(actions)+1L]] <- c(list(number=length(actions), source=candidate$source,
            arguments=candidate$arguments, cost=candidate$cost), mapped)
    }
    initial <- sort(unname(fact_numbers[initial_atoms[vapply(problem$initial, function(a) a[1] %in% domain$fluent, FALSE)]]))
    goal <- integer()
    unreachable <- list()
    for (atom in problem$goals) {
        key <- notation(atom)
        if (key %in% fact_keys) goal <- union(goal, fact_numbers[[key]]) else {
            if (!atom[1] %in% domain$static || !key %in% initial_atoms) unreachable[[length(unreachable)+1L]] <- atom
        }
    }
    action_numbers <- setNames(vapply(actions, function(a) a$number, 0L), vapply(actions, action_text, ""))
    list(name=problem$name, source=problem, objects_by_type=objects_by_type, statistics=statistics,
        candidate_count=length(candidates), facts=facts, actions=actions, initial=initial, goal=sort(goal),
        unreachable=unreachable, static_count=sum(vapply(problem$initial, function(a) a[1] %in% domain$static, FALSE)),
        action_numbers=action_numbers)
}

HEURISTIC_NAMES <- c("goalcount", "hmax", "hadd", "ff", "lmcount")
INFINITY <- .Machine$integer.max
state_key <- function(state) paste0("s", paste(sort(state), collapse=","))
new_evaluator <- function(problem) {
    engine <- new.env(parent=emptyenv())
    engine$problem <- problem
    engine$achievers <- rep(list(integer()), length(problem$facts))
    for (action in problem$actions) for (fact in action$add) {
        engine$achievers[[fact+1L]] <- c(engine$achievers[[fact+1L]], action$number)
    }
    engine$cache <- new.env(hash=TRUE, parent=emptyenv())
    engine
}
cached <- function(engine, name, state, compute) {
    key <- paste(name, state_key(state))
    if (exists(key, engine$cache, inherits=FALSE)) return(engine$cache[[key]])
    value <- compute()
    engine$cache[[key]] <- value
    value
}
relaxed_costs <- function(engine, state, maximum_cost) {
    cached(engine, if (maximum_cost) "cmax" else "cadd", state, function() {
        costs <- ifelse((seq_along(engine$problem$facts)-1L) %in% state, 0L, INFINITY)
        repeat {
            changed <- FALSE
            for (action in engine$problem$actions) {
                values <- costs[action$pre+1L]
                if (INFINITY %in% values) next
                aggregate <- if (maximum_cost) max(c(0L, values)) else sum(values)
                value <- action$cost+aggregate
                for (p in action$add) if (value < costs[p+1L]) {
                    costs[p+1L] <- value
                    changed <- TRUE
                }
            }
            if (!changed) break
        }
        costs
    })
}
relaxed_plan <- function(engine, state) {
    cached(engine, "plan", state, function() {
        costs <- relaxed_costs(engine, state, FALSE)
        if (any(costs[engine$problem$goal+1L] == INFINITY)) return(NULL)
        chosen <- integer()
        pending <- sort(setdiff(engine$problem$goal, state))
        while (length(pending)) {
            fact <- tail(pending, 1)
            pending <- head(pending, -1)
            winner <- -1L
            lowest <- INFINITY
            for (number in engine$achievers[[fact+1L]]) {
                action <- engine$problem$actions[[number+1L]]
                values <- costs[action$pre+1L]
                if (INFINITY %in% values) next
                value <- action$cost+sum(values)
                if (value < lowest) {
                    winner <- number
                    lowest <- value
                }
            }
            if (!winner %in% chosen) {
                chosen <- c(chosen, winner)
                pending <- c(pending, sort(setdiff(engine$problem$actions[[winner+1L]]$pre, state)))
            }
        }
        sort(chosen)
    })
}
helpful <- function(engine, state) {
    plan <- relaxed_plan(engine, state)
    plan[vapply(plan, function(n) applicable(engine$problem$actions[[n+1L]], state), FALSE)]
}
planning_levels <- function(engine, state) {
    cached(engine, "levels", state, function() {
        facts <- ifelse((seq_along(engine$problem$facts)-1L) %in% state, 0L, INFINITY)
        actions <- rep(INFINITY, length(engine$problem$actions))
        level <- 0L
        repeat {
            changed <- FALSE
            for (action in engine$problem$actions) {
                if (actions[action$number+1L] != INFINITY || any(facts[action$pre+1L] > level)) next
                actions[action$number+1L] <- level
                for (p in action$add) if (facts[p+1L] == INFINITY) {
                    facts[p+1L] <- level+1L
                    changed <- TRUE
                }
            }
            if (!changed) return(list(facts=facts, actions=actions))
            level <- level+1L
        }
    })
}
verified_landmark <- function(engine, state, excluded) {
    reachable <- state
    repeat {
        changed <- FALSE
        for (action in engine$problem$actions) {
            if (excluded %in% action$add || !all(action$pre %in% reachable)) next
            added <- setdiff(action$add, reachable)
            if (length(added)) {
                reachable <- union(reachable, added)
                changed <- TRUE
            }
        }
        if (!changed) break
    }
    !all(engine$problem$goal %in% reachable)
}
landmarks <- function(engine, state) {
    cached(engine, "landmarks", state, function() {
        levels <- planning_levels(engine, state)
        if (any(levels$facts[engine$problem$goal+1L] == INFINITY)) return(NULL)
        selected <- setdiff(engine$problem$goal, state)
        pending <- sort(selected)
        verified <- list()
        head <- 1L
        while (head <= length(pending)) {
            fact <- pending[head]
            head <- head+1L
            numbers <- engine$achievers[[fact+1L]]
            numbers <- numbers[levels$actions[numbers+1L] == levels$facts[fact+1L]-1L]
            earliest <- lapply(numbers, function(n) engine$problem$actions[[n+1L]]$pre)
            candidates <- earliest[[1]]
            for (pre in earliest[-1]) candidates <- intersect(candidates, pre)
            for (p in sort(setdiff(candidates, union(state, selected)))) {
                key <- as.character(p)
                if (is.null(verified[[key]])) verified[[key]] <- verified_landmark(engine, state, p)
                if (verified[[key]]) {
                    selected <- union(selected, p)
                    pending <- c(pending, p)
                }
            }
        }
        sort(selected)
    })
}
heuristic_value <- function(engine, name, state) {
    if (name == "none") return(0L)
    cached(engine, name, state, function() {
        if (name == "goalcount") return(length(setdiff(engine$problem$goal, state)))
        if (name %in% c("hmax", "hadd")) {
            costs <- relaxed_costs(engine, state, name == "hmax")
            values <- costs[engine$problem$goal+1L]
            if (INFINITY %in% values) return(INFINITY)
            return(if (name == "hmax") max(c(0L, values)) else sum(values))
        }
        if (name == "ff") {
            plan <- relaxed_plan(engine, state)
            return(if (is.null(plan)) INFINITY else sum(vapply(plan, function(n) engine$problem$actions[[n+1L]]$cost, 0L)))
        }
        selected <- landmarks(engine, state)
        if (is.null(selected)) INFINITY else length(selected)
    })
}
heuristic_values <- function(engine, state) vapply(HEURISTIC_NAMES, function(name) heuristic_value(engine, name, state), 0)

